'use strict';
// Nightly. Writes exports/agent-weekly-summary.json: for every agent who owns at least one ticket rated in the
// past seven days, how many ratings they got and the average score. Read by team leads.
const fs = require('node:fs');
const path = require('node:path');

const WINDOW_DAYS = 7;
const DAY = 24 * 60 * 60 * 1000;
const EXPORT_DIR = path.join(__dirname, '..', '..', 'exports');

function agentWeeklySummary(store, { now = new Date(), dir = EXPORT_DIR } = {}) {
  const byAgent = new Map();
  for (const t of store.listTickets()) {
    if (t.rating_score == null || t.owner_id == null) continue;
    if (now.getTime() - new Date(t.rated_at).getTime() >= WINDOW_DAYS * DAY) continue;
    if (!byAgent.has(t.owner_id)) byAgent.set(t.owner_id, []);
    byAgent.get(t.owner_id).push(t.rating_score);
  }
  const rows = [...byAgent.entries()]
    .map(([agentId, scores]) => ({
      agent_id: agentId,
      ratings: scores.length,
      average: Math.round((scores.reduce((sum, s) => sum + s, 0) / scores.length) * 100) / 100,
    }))
    .sort((a, b) => a.agent_id - b.agent_id);
  fs.mkdirSync(dir, { recursive: true });
  const file = path.join(dir, 'agent-weekly-summary.json');
  fs.writeFileSync(file, JSON.stringify(rows, null, 2) + '\n');
  return { file, rows };
}

module.exports = { agentWeeklySummary, WINDOW_DAYS };
